from acme_index import EmbedderError


class FlakyEmbedder(FakeEmbedder):
    fail = False

    def embed(self, texts: list[str]) -> list[list[float]]:
        if self.fail:
            raise EmbedderError("embedder down")
        return super().embed(texts)


class ReindexFailureTests(unittest.TestCase):
    def test_reindex_keeps_the_old_version_when_embedding_fails(self) -> None:
        embedder = FlakyEmbedder()
        with tempfile.TemporaryDirectory() as folder:
            store = Store(Path(folder) / "t.sqlite", embedder)
            store.add_document("a", "banana salata")
            embedder.fail = True
            with self.assertRaises(EmbedderError):
                store.reindex("a", "nova verzija")
            self.assertEqual(store.count("a"), 1)  # today 0: the delete was already committed
            store.close()

class AnswerEndTests(unittest.TestCase):
    def stream(self, raw: bytes) -> list[dict]:
        with mock.patch("urllib.request.urlopen", return_value=io.BytesIO(raw)):
            return list(Answerer("http://model.example.com").stream_answer("Where?", []))

    def assert_ends_with_one_error(self, events: list[dict]) -> None:
        closing = [event["type"] for event in events if event["type"] in ("end", "error")]
        self.assertEqual(closing, ["error"])
        self.assertEqual(events[-1]["type"], "error")

    def test_a_malformed_line_ends_the_stream_with_an_error(self) -> None:
        self.assert_ends_with_one_error(self.stream(b'{"text": "Novi "}\nnot json\n'))

    def test_a_message_without_text_ends_the_stream_with_an_error(self) -> None:
        self.assert_ends_with_one_error(self.stream(b'{"error": "overloaded"}\n'))

    def test_a_stream_cut_before_done_is_an_error_not_an_end(self) -> None:
        self.assert_ends_with_one_error(self.stream(b'{"text": "Novi "}\n'))
